WITH lines AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(tier_prices) AS val FROM price_tiers) SELECT currency, ROUND(SUM(val) / NULLIF(COUNT(CASE WHEN plan = 'pro' THEN 1 END), 0), 2) AS val_per_pro, SUM(CASE WHEN currency = 'EUR' THEN val ELSE 0 END) AS eur_val, COUNT_IF(plan = 'pro') AS pro_events FROM lines GROUP BY currency ORDER BY val_per_pro DESC NULLS LAST;
